// Original classroom explanations and worked examples. Sources are optional further reading.
const ibm='https://quantum.cloud.ibm.com/learning/en/courses/';
const ref=(label,url)=>({label,url});
const states=ref('IBM · Quantum states and measurement',ibm+'basics-of-quantum-information/single-systems/quantum-information');
const circuits=ref('IBM · Quantum circuits',ibm+'basics-of-quantum-information/quantum-circuits/introduction');
const pairs=ref('IBM · Multiple quantum systems',ibm+'basics-of-quantum-information/multiple-systems/quantum-information');
const tel=ref('IBM · Quantum teleportation',ibm+'basics-of-quantum-information/entanglement-in-action/quantum-teleportation');
const mixed=ref('IBM · Mixed states',ibm+'general-formulation-of-quantum-information/density-matrices/introduction');
const nist=ref('NIST · Post-quantum cryptography','https://www.nist.gov/cybersecurity-and-privacy/what-post-quantum-cryptography');
const step=(title,explanation,notice,visual)=>({title,explanation,notice,visual});
const flow=(nodes,active=0)=>({type:'flow',nodes:nodes.map(([label,detail])=>({label,detail})),active});
const bars=(labels,values,caption)=>({type:'bars',labels,values,caption});
const sphere=(vector,caption)=>({type:'sphere',vector,caption});
const circuit=(gates,caption)=>({type:'circuit',gates,caption});
const compare=(lt,ll,rt,rl)=>({type:'compare',left:{title:lt,lines:ll},right:{title:rt,lines:rl}});
const bits=(rows,caption)=>({type:'bits',rows:rows.map(([label,values])=>({label,values})),caption});
export const STORIES={
 welcome:{title:'Start your quantum journey from zero',summary:'Learn what a computer does, what a bit represents and how this workshop introduces quantum ideas.',source:ref('IBM · Quantum learning resources','https://quantum.cloud.ibm.com/learning'),steps:[
  step('What is computing?','Computing means representing information and following instructions to produce a result. For example, a calculator receives two numbers, follows an addition instruction and displays their sum. Your phone and laptop do this with many kinds of information. Begin with the information and the task before thinking about the device that performs it.','Input, instructions and output have different jobs.',flow([['Input','Two numbers: 2 and 3'],['Instruction','Add the numbers'],['Output','The result: 5']],1)),
  step('How does an ordinary computer represent information?','A classical bit is a unit of information with two possible values: 0 or 1. A switch gives us a simple picture: off represents 0 and on represents 1. Computers combine many bits to encode numbers, text and pictures. A physical computer uses electrical components; the switch here is an analogy for its two logical values.','A bit records one definite value, even when we do not know which value it holds.',compare('Bit value 0',['Switch analogy: OFF','One recorded value'],'Bit value 1',['Switch analogy: ON','One recorded value'])),
  step('What makes a qubit different?','A qubit is a quantum system with two reference states, named |0⟩ and |1⟩. You can read those symbols as “state zero” and “state one.” Its state can also be a superposition, which we will explain visually next. One measurement still produces one classical outcome; it does not display two readable answers at the same time.','Keep the quantum state separate from the measurement result.',compare('Before measurement',['Prepare a quantum state','Operations can change it'],'After one measurement',['Record one classical outcome','Repeat fresh trials to learn a pattern'])),
  step('What will we learn each day?','The workshop builds a path from information to experiments. Monday introduces qubits, the Bloch sphere, gates and circuits. Tuesday connects networks, polarization and quantum key distribution. Thursday distinguishes post-quantum cryptography. Friday develops technician and Python skills. Saturday explores classical waves with instruments and explains which ideas connect to quantum interference.','Learn the foundations first; later days apply them to communication, programs and measurements.',flow([['Monday','Qubits, gates and circuits'],['Tuesday','Communication and QKD'],['Thursday','Post-quantum cryptography'],['Friday','Technician skills and Python'],['Saturday','Classical wave laboratory']],0)),
  step('How will we know what a result means?','Read the explanation, inspect the diagram, make a prediction and then try the control or guided example. A browser simulation calculates a model; it is not a measurement from quantum hardware. In the physical wave lab, the instruments measure classical electrical signals. Label the source of each result and explain both what it shows and what remains untested.','Explain → predict → try → interpret, then answer the practice question.',compare('Browser activity',['Learn with an ideal model','Results are calculated or simulated'],'Instrument activity',['Record equipment and settings','Results describe the measured classical circuit']))
 ]},
 qubit:{title:'From a bit to a qubit',summary:'Begin with a familiar switch, then separate a quantum state from the result of measuring it.',source:states,steps:[
  step('Start with one classical bit','A classical bit records one of two values: 0 or 1. A switch is a useful picture: off can represent 0 and on can represent 1. Real computers combine many bits to represent words, pictures and numbers. First keep the stored value separate from any uncertainty about what it is.','One bit has two possible values.',compare('Classical 0',['Switch: OFF','Recorded value: 0'],'Classical 1',['Switch: ON','Recorded value: 1'])),
  step('Meet the two quantum reference states','A qubit is a physical quantum system with two chosen reference states. We label them |0⟩ and |1⟩; the brackets simply identify quantum states. For example, two polarization directions of a photon can serve as these references. The labels describe information, not two tiny numbers printed on a particle.','The symbols |0⟩ and |1⟩ name reference states.',sphere([0,0,1],'Prepared |0⟩: a Z measurement returns 0 with certainty in the ideal model.')),
  step('Prepare a superposition','A Hadamard gate, abbreviated H, changes |0⟩ into |+⟩ = (|0⟩ + |1⟩)/√2. This is one quantum state described by two amplitudes. Squaring the magnitude of each amplitude gives one half. Therefore a Z measurement has a 50% chance of returning 0 and a 50% chance of returning 1.','The amplitudes are 1/√2; the probabilities are 1/2.',circuit(['H'],'Starting at |0⟩, H prepares |+⟩. Measurement comes after preparation.')),
  step('Understand relative phase','Two states can predict the same Z probabilities and still behave differently. The state |+⟩ combines its two amplitudes with the same sign; |−⟩ combines them with opposite signs. That difference is a relative phase of 180°. Both give 50/50 in Z, but X measurement gives + with certainty for |+⟩ and − with certainty for |−⟩. Phase describes how amplitudes combine, not an extra outcome read from one qubit.','Change the measurement basis to see the effect of relative phase.',compare('|+⟩: same sign',['Z: 0 or 1, each 50%','X: + with certainty'],'|−⟩: opposite signs',['Z: 0 or 1, each 50%','X: − with certainty'])),
  step('Read one outcome','Measuring that prepared qubit in Z returns a single classical value: 0 or 1. It does not reveal both amplitudes. In an ideal projective measurement the state then becomes the reference state for the observed outcome. For example, after observing 1, immediately measuring again in the same basis returns 1.','One measurement gives one result, not a complete state description.',flow([['Prepare |+⟩','Equal Z probabilities'],['Measure in Z','One random result'],['Example: 1','State becomes |1⟩'],['Measure Z again','1 again, ideally']],2)),
  step('Repeat a preparation to learn its probabilities','To investigate the original 50/50 prediction, prepare |+⟩ again before every trial. A run of 100 trials might give 47 zeros and 53 ones; another run will differ. Probabilities describe repeated preparations. Quantum computing uses carefully designed operations to change those probabilities before a useful result is measured.','A sample count fluctuates; an exact prediction need not.',compare('Ideal prediction',['0: 50%','1: 50%'],'Illustrative 100 trials',['0: 47 results','1: 53 results']))
 ]},
 bloch:{title:'Read the Bloch sphere one direction at a time',summary:'The sphere is a map of one-qubit states. Its arrow is a mathematical description, not a particle orbit.',source:states,steps:[
  step('Locate the two poles','Place |0⟩ at the north pole and |1⟩ at the south pole. These are the positive and negative Z directions. A pure one-qubit state appears as a point on the sphere surface. The arrow starts at the center and ends at that point; it is a map of the state, not a physical trajectory.','North and south mean opposite Z reference states.',sphere([0,0,1],'North pole: +Z, or |0⟩. The opposite pole is |1⟩.')),
  step('Move from a pole toward the equator','The angle θ, pronounced theta, measures how far the arrow tilts away from the north pole. Its Z probabilities are P(0) = cos²(θ/2) and P(1) = sin²(θ/2). At θ = 60°, they are 75% and 25%. The half-angle is part of the quantum-state mapping.','θ = 60° does not mean a 60% probability.',bars(['0','1'],[.75,.25],'Z measurement for θ = 60°: cos²(30°) = 0.75.')),
  step('Find the equator and relative phase','At θ = 90°, every point on the equator gives 50/50 in Z. Moving around that equator changes the relative phase φ, pronounced phi. The +X point is |+⟩, while the opposite −X point is |−⟩. Equal Z probabilities do not make those two states identical.','Phase changes the direction even when Z probabilities stay fixed.',sphere([1,0,0],'|+⟩ sits on +X. The opposite equator point is |−⟩.')),
  step('Ask a different measurement question','Choose the X basis when you want outcomes labeled + and − instead of 0 and 1. For |+⟩, X gives + with certainty. For the same state, Z gives 0 or 1 equally often. Changing the basis changes the question asked of the state; it does not mean reading more than one outcome from one measurement.','The state and the chosen basis jointly determine the prediction.',compare('Measure |+⟩ in Z',['0: 50%','1: 50%'],'Measure |+⟩ in X',['+: 100%','−: 0%'])),
  step('Interpret an arrow inside the sphere','Not every state lies on the surface. Mixed states occupy the interior. The center predicts equally likely outcomes for any measurement axis. A shorter arrow can represent reduced coherence or uncertainty in preparation. It does not mean the physical qubit shrank, and one sphere cannot represent a general entangled two-qubit state.','Surface: pure state. Interior: mixed state.',sphere([.5,0,0],'A mixed state halfway toward +X gives 75% + in X and 50% 0 in Z.'))
 ]},
 superposition:{title:'See what superposition adds',summary:'Track amplitudes, phase and measurement instead of imagining two visible answers at once.',source:states,steps:[
  step('Choose reference outcomes','Before describing a superposition, choose a basis: a pair of reference states that defines a measurement. In the Z basis these are |0⟩ and |1⟩. Saying a state is a superposition is relative to that choice. A state can be a reference state in one basis and a superposition in another.','A basis tells us what the possible measurement outcomes mean.',compare('Z basis',['Reference states: |0⟩, |1⟩','Readouts: 0 or 1'],'X basis',['Reference states: |+⟩, |−⟩','Readouts: + or −'])),
  step('Give both amplitudes a role','Prepare |+⟩ by applying H to |0⟩. The two Z-basis amplitudes are equal and have the same phase. Each contributes half of the total Z-measurement probability. Amplitudes are numbers in the state description; they can have a sign or complex phase, unlike ordinary probabilities, which cannot be negative.','The quantum state carries more than a list of probabilities.',sphere([1,0,0],'|+⟩: equal Z amplitudes with the same phase.')),
  step('Change phase without changing Z probabilities','Applying Z to |+⟩ changes it into |−⟩. The |1⟩ amplitude now has the opposite sign. Z measurements still give 50/50 for both states. The sign difference becomes observable only through a suitable later operation or a different measurement basis. A Z histogram alone misses this distinction.','Same Z probabilities can come from different quantum states.',compare('|+⟩',['Amplitudes: +1/√2, +1/√2','Z probabilities: 50%, 50%'],'|−⟩',['Amplitudes: +1/√2, −1/√2','Z probabilities: 50%, 50%'])),
  step('Turn the phase difference into an outcome','Apply H once more. H maps |+⟩ to |0⟩ and |−⟩ to |1⟩. Now a Z measurement distinguishes the two preparations. This is a small example of interference: contributions combine differently because of their phases. The result follows from the ordered operations, not from observing two answers simultaneously.','H → H predicts 0; H → Z → H predicts 1.',compare('Start |0⟩ → H → H',['Final state: |0⟩','Z result: 0'],'Start |0⟩ → H → Z → H',['Final state: |1⟩','Z result: 1'])),
  step('Compare with ordinary randomness','An ordinary random preparation that chooses |0⟩ or |1⟩ with equal chance also gives 50/50 in Z. However, measuring that mixture in X still gives 50/50. Measuring |+⟩ in X gives + every time. This comparison explains why a coherent superposition is different from simply not knowing a stored classical value.','Use another basis to reveal the distinction.',compare('Coherent |+⟩',['Z: 50/50','X: + with certainty'],'Random 0/1 mixture',['Z: 50/50','X: 50/50']))
 ]},
 gates:{title:'Read a quantum circuit as an ordered recipe',summary:'Prepare a state, apply one operation at a time, and predict the final measurement.',source:circuits,steps:[
  step('Start with preparation','This walkthrough begins by preparing |0⟩. A circuit wire represents one qubit as operations occur from left to right. Boxes label gates; a measurement symbol indicates conversion to a classical result. Preparation and measurement are different tasks from the ideal reversible gates between them. Always identify the input before interpreting a gate.','A gate has no single output independent of its input.',flow([['Prepare','Start at |0⟩'],['Gates','Change the state'],['Measure','Record a classical bit']],0)),
  step('Use X to exchange the reference states','The X gate exchanges |0⟩ and |1⟩. From the chosen input |0⟩, one X therefore makes the Z result 1. Applying X twice restores the starting state. On a superposition, X acts on both amplitudes according to the same operation; it is not a command to force every possible input to 1.','X swaps; it does not mean “set to 1.”',circuit(['X'],'Prepared |0⟩ becomes |1⟩. A final Z measurement gives 1.')),
  step('Use H to change between reference bases','The H gate maps |0⟩ to |+⟩ and |1⟩ to |−⟩. Applied in reverse, the same gate maps |+⟩ back to |0⟩ and |−⟩ back to |1⟩. Thus H can create an equal Z-basis superposition from a pole, but it does not produce 50/50 Z probabilities for every input.','Two H gates undo each other.',circuit(['H','H'],'From |0⟩, the first H prepares |+⟩ and the second returns |0⟩.')),
  step('Use Z to change relative phase','Z leaves |0⟩ unchanged and changes the sign of the |1⟩ amplitude. Applied to |+⟩, it produces |−⟩. Their Z probabilities are identical, so insert a final H to make the phase difference visible. In this example H → Z → H produces |1⟩ from the initial |0⟩.','A phase change can matter even before a histogram changes.',circuit(['H','Z','H'],'Z changes the phase between H gates; final Z readout is 1.')),
  step('Respect the order of operations','Compare two short recipes beginning at |0⟩. Z then H produces |+⟩, whereas H then Z produces |−⟩. They have the same Z histogram but opposite definite X outcomes. This shows that gates cannot generally be reordered. In a larger circuit, keep track of which qubit each operation acts on as well.','Read left to right, and keep the measurement basis in the prediction.',compare('Z → H',['State: |+⟩','X result: +'],'H → Z',['State: |−⟩','X result: −']))
 ]},
 interference:{title:'Follow phase until it changes a probability',summary:'A complete H → phase → H example shows why quantum amplitudes must be combined before probabilities are calculated.',source:states,steps:[
  step('Prepare equal amplitudes','Begin at |0⟩ and apply H. The resulting state |+⟩ has equal Z-basis amplitudes. If we measure now, the probabilities are 50% for 0 and 50% for 1. Instead, keep the state coherent so a later operation can combine the amplitudes. Measuring midway would change the experiment.','Do not measure between the gates in this example.',circuit(['H'],'After the first H, stop before measurement: both Z outcomes have probability 1/2.')),
  step('Change a relative phase','A phase gate P(φ) rotates the phase of the |1⟩ amplitude while leaving the |0⟩ amplitude unchanged. At this intermediate point the magnitudes have not changed, so the Z probabilities remain 50/50. Think of complex amplitudes as arrows: their lengths determine magnitudes, while their directions carry phase information.','Relative phase changes arrow directions, not their lengths.',sphere([0,1,0],'At φ = 90°, the equal superposition lies on +Y; Z is still 50/50.')),
  step('Recombine with the second H','The second H combines the two contributions to each output amplitude. For outcome 0, the amplitude becomes (1 + eⁱφ)/2. First add those contributions, then take the squared magnitude. The result is P(0) = cos²(φ/2). This order of calculation is the central idea behind interference.','Add amplitudes first; calculate probabilities second.',circuit(['H','P(φ)','H'],'The final H makes the relative phase observable in a Z measurement.')),
  step('Compare three useful settings','At φ = 0°, the contributions to outcome 0 reinforce and P(0) = 1. At 90°, both outcomes have probability 1/2. At 180°, the contributions to outcome 0 cancel, leaving P(0) = 0. Outcome 1 receives the remaining probability, so the total stays one.','Cancellation removes an output amplitude, not the total probability.',bits([['Phase',['0°','90°','180°']],['P(0)',['100%','50%','0%']],['P(1)',['0%','50%','100%']]],'Predictions after the complete H → P(φ) → H circuit.')),
  step('Connect the lab analogy carefully','Two classical voltage waves can reinforce or cancel when their relative phase changes. That makes an oscilloscope useful for introducing phase. The quantum circuit instead combines probability amplitudes. A matching mathematical curve helps us compare ideas, but a resistor circuit and its voltage trace do not create or measure a qubit.','Similar mathematics does not make the physical systems identical.',compare('Oscilloscope lab',['Quantity: voltage','Measured in volts','Classical wave addition'],'Quantum circuit',['Quantity: amplitude','Predicts outcome probabilities','Requires quantum state preparation']))
 ]},
 entanglement:{title:'Build and test one Bell pair',summary:'Two qubits can need a joint description, even when each local outcome looks random.',source:pairs,steps:[
  step('Label both qubits','Alice has qubit A and Bob has qubit B. Begin with both prepared as 0, written |00⟩. In this lesson, the first symbol always refers to Alice and the second to Bob. Four Z readouts are possible for a general two-qubit state: 00, 01, 10 and 11.','Fix the order A then B before reading any pair of bits.',bars(['00','01','10','11'],[1,0,0,0],'Starting state |00⟩: only one Z outcome is possible.')),
  step('Create a superposition on Alice’s qubit','Apply H to A while leaving B at 0. The joint state is now (|00⟩ + |10⟩)/√2. Alice has an equal superposition and Bob is still definitely 0. At this stage the state can be described separately for each qubit; a superposition on one qubit alone is not entanglement.','Bob has not yet become correlated with Alice.',bars(['00','01','10','11'],[.5,0,.5,0],'After H on A: the two components are 00 and 10.')),
  step('Apply the controlled operation','Apply CNOT with A as control and B as target. It leaves the 00 component unchanged and turns the 10 component into 11. The result is (|00⟩ + |11⟩)/√2, a Bell state. Its coherent joint description cannot be written as one independent pure state for A multiplied by one for B.','The operation links the two components into an entangled state.',bits([['Before CNOT',['00','10']],['After CNOT',['00','11']]],'Amplitudes remain equal and coherent. This is the Bell state |Φ+⟩.')),
  step('Measure many fresh pairs in Z','Prepare a new Bell pair for every trial and measure both qubits in Z. The ideal joint outcomes are 00 or 11, each with probability one half. Alice alone sees random bits, and so does Bob. Looking only at these matching Z results cannot distinguish this Bell state from a classical 00/11 mixture.','Shared Z results alone do not prove entanglement.',bars(['00','01','10','11'],[.5,0,0,.5],'Joint Z/Z probabilities. Each local observer still sees 50/50.')),
  step('Compare a second basis','Repeat the experiment with both qubits measured in X. The Bell state |Φ+⟩ gives matching +/+ or −/− results. A classical mixture of 00 and 11 gives all four X/X combinations equally often. Comparing multiple settings therefore tests predictions that a single matching histogram cannot reveal.','Change both analyzers to X and compare the two preparations.',compare('Bell state in X/X',['++: 50%; −−: 50%','Opposite results: 0%'],'Classical 00/11 mixture in X/X',['++, +−, −+, −−','Each: 25%'])),
  step('Keep correlation separate from communication','Alice cannot choose her random measurement result. Bob’s own outcomes remain equally likely whether Alice chooses Z or X. To discover the correlations, they must later compare their records through ordinary communication. Entanglement is a property of the joint state, not a controllable signal that instantly carries a chosen message.','Comparing records requires a classical communication channel.',flow([['Alice','Random local record'],['Ordinary channel','Compare settings and results'],['Bob','Random local record']],1))
 ]},
 teleportation:{title:'Transfer a state in six visible steps',summary:'Track three qubits, one shared Bell pair, two classical bits and Bob’s correction.',source:tel,steps:[
  step('Identify the input and the resources','Alice holds the input qubit Q in an unknown state |ψ⟩, pronounced psi. Alice also holds qubit A, and Bob holds qubit B. A and B share a Bell pair. The goal is for B to acquire Q’s original state. The input and the shared pair are separate resources, so there are three qubits.','The goal concerns a state; the particles themselves are not transported.',flow([['Q at Alice','Unknown input |ψ⟩'],['A at Alice','Half of a Bell pair'],['B at Bob','Other half of the pair']],0)),
  step('Let Alice combine her two qubits','Alice applies CNOT from Q to A, then H on Q. These gates arrange correlations so that measuring her two qubits will tell Bob which correction is needed. She does not first read out the amplitudes of |ψ⟩. An unknown state cannot be fully learned from one measurement of a single input.','Alice operates locally on Q and A; Bob has not recovered the input yet.',flow([['CNOT Q → A','Q controls A'],['H on Q','Change the Q basis'],['Two Z measurements','Next step']],1)),
  step('Measure and write two ordinary bits','Alice measures Q and A in Z and records two bits in the order mQ mA. The four branches 00, 01, 10 and 11 are equally likely in the ideal protocol. Her measurements remove the original input state from Q. The branch selector in the demonstration lets us inspect a possibility; Alice cannot choose that result.','The displayed bit order is Q first, A second.',bars(['00','01','10','11'],[.25,.25,.25,.25],'Four possible measurement branches, each with probability 25%.')),
  step('Send the measurement record to Bob','Alice sends mQ and mA over an ordinary communication channel. These two bits do not describe the input amplitudes. They identify which transformation Bob must undo using his half of the shared resource. Before that record is available, Bob’s local state does not reveal the unknown input. The protocol therefore cannot transmit a usable state faster than light.','Two classical bits must arrive before the appropriate correction.',bits([['mQ mA',['00','01','10','11']],['Correction',['None','X','Z','X then Z']]],'The A bit controls X; the Q bit controls Z.')),
  step('Apply the indicated correction','Consider branch 01: Q measured 0 and A measured 1. Bob applies X, but not Z. For branch 10 he applies Z only. For 11 he applies X and then Z. After the correct operation, B has the original input state in the ideal model, up to an unobservable overall phase.','Try every branch; each correction restores the same input state.',flow([['Received 01','mQ = 0, mA = 1'],['Apply X','A bit is 1'],['B holds |ψ⟩','Input state recovered']],1)),
  step('Check what remains afterward','Bob now holds the transferred state. Alice no longer holds a second intact copy on Q, and the original A–B Bell resource has been consumed. A picture of the initial state may remain onscreen as a comparison reference, but it is not another physical qubit in that state. This distinction keeps teleportation consistent with no-cloning.','One recovered output, no surviving original copy.',compare('Before',['Q carries |ψ⟩','A–B form a Bell pair'],'After',['B carries |ψ⟩','Q and A have been measured']))
 ]},
 nocloning:{title:'Why a quantum state is not a copyable file',summary:'Test a familiar-looking copier on basis states, then discover where it fails.',source:circuits,steps:[
  step('Begin with a copier that seems to work','Use CNOT with the input qubit as control and a target prepared at |0⟩. If the input is |0⟩, the pair remains |00⟩. If the input is |1⟩, the pair becomes |11⟩. These two orthogonal reference states can be copied in this way, just like two distinguishable classical values.','Success on 0 and 1 is only a limited test.',bits([['Input + blank',['00','10']],['CNOT output',['00','11']]],'The target begins at 0 in both examples.')),
  step('Choose a new input','Now prepare the input as |+⟩ while keeping the target at |0⟩. If the device were a universal copier, its output would be two independent |+⟩ states. That desired product state would give 00, 01, 10 and 11 with equal probabilities in Z. This is a different test from copying a known basis value.','A universal copier must also work for superpositions.',bars(['00','01','10','11'],[.25,.25,.25,.25],'Desired independent copies |+⟩|+⟩: four equally likely Z outcomes.')),
  step('Calculate what CNOT actually does','CNOT acts on both components of the input state. It keeps 00 and turns 10 into 11, producing (|00⟩ + |11⟩)/√2. The output is entangled. Its Z results can only be 00 or 11, unlike the four outcomes predicted for two independent |+⟩ copies. The supposed copier has failed this input.','An entangled pair is not two independent copies.',bars(['00','01','10','11'],[.5,0,0,.5],'Actual output from CNOT: the Bell state, not |+⟩|+⟩.')),
  step('State the limit precisely','No single physical operation can perfectly copy every arbitrary unknown quantum state. This is the no-cloning theorem. It does not mean that a known state can never be prepared twice, nor that classical records cannot be copied. The limitation concerns a universal perfect copier that receives one unknown quantum input.','“Arbitrary unknown state” and “perfect” are essential parts of the statement.',compare('Allowed',['Copy a classical bit','Prepare a known recipe twice'],'Not universally possible',['Receive one unknown state','Output two perfect independent copies'])),
  step('Connect the limit to communication','In BB84, an observer cannot make perfect copies of all possible nonorthogonal signal states and postpone every measurement without affecting the protocol assumptions. This is part of the physical motivation for QKD. Security still needs a full protocol and analysis. No-cloning by itself does not authenticate a sender or certify a deployed device.','A quantum principle supports the protocol; it is not the whole security system.',flow([['Unknown signal','No universal perfect copy'],['Possible disturbance','Test with a full protocol'],['Security decision','Requires assumptions and analysis']],0))
 ]},
 noise:{title:'Watch phase coherence fade',summary:'Use one simple dephasing model to see why a Z histogram can conceal a change in the state.',source:mixed,steps:[
  step('Establish a coherent reference','Prepare |+⟩. Its Bloch vector points along +X, so X measurement gives + with certainty. Z measurement gives 0 or 1 with equal probabilities. Record both predictions before introducing noise. Testing only one basis can hide important state changes, because different states may share the same histogram in that basis.','Use X as well as Z to inspect this state.',sphere([1,0,0],'Initial coherent state |+⟩. Vector length is 1.')),
  step('Introduce the model parameter','The slider models dephasing with strength d between 0 and 1. It reduces the X and Y components while preserving Z. This describes loss of relative-phase coherence in one simplified model. It is not every kind of hardware noise, and the number d is not an elapsed time or a measured device lifetime.','This model changes coherence while preserving Z populations.',sphere([.5,0,0],'At d = 0.5, the original +X vector has half its length.')),
  step('See a probability change in X','For the partially dephased example d = 0.5, the X outcomes become 75% + and 25% −. The original state gave + with certainty. In Z, both the original and changed states still give 50/50. The experiment must use a measurement setting that is sensitive to the property being tested.','An unchanged Z histogram does not mean the state stayed unchanged.',compare('Z measurement',['Before: 50/50','After d = 0.5: 50/50'],'X measurement',['Before: 100% +','After d = 0.5: 75% +'])),
  step('Reach the fully dephased case','At d = 1, the vector reaches the center for this initial |+⟩ example. X outcomes are now 50/50 as well as Z outcomes. The phase coherence that produced a definite X result has disappeared in the model. The qubit has not physically become smaller; the interior point describes a mixed quantum state.','At the center, every measurement axis has balanced outcomes.',sphere([0,0,0],'Fully dephased |+⟩ becomes the equal 0/1 mixture.')),
  step('Separate more data from noise protection','Collecting more fresh trials improves the estimate of the noisy probabilities. It does not restore the missing coherence. Protecting quantum information requires suitable control, isolation and, for quantum error correction, additional physical resources and a designed protocol. Always distinguish random variation in a small sample from a systematic change caused by noise.','More shots reduce sampling uncertainty, not physical decoherence.',compare('More samples',['Estimate a distribution better','Reduce statistical uncertainty'],'Noise protection',['Change hardware/control/protocol','Address physical state errors']))
 ]},
 polarization:{title:'Read polarization through an analyzer',summary:'Begin with classical light intensity, then relate the same angle rule to an ideal single-photon measurement.',source:ref('Harvard · Malus’s law','https://sciencedemonstrations.fas.harvard.edu/presentations/malus-law'),steps:[
  step('Identify a polarization direction','For linearly polarized light, the electric field oscillates along a chosen direction perpendicular to travel. The line in the illustration represents that orientation. It does not show the photon moving up and down along the drawn line. Horizontal and vertical can serve as two distinguishable reference polarizations.','Propagation direction and polarization direction are different ideas.',{type:'polar',angle:0,caption:'Aligned linear polarization and analyzer: angle difference 0°.'}),
  step('Align the analyzer','An ideal linear analyzer selects the component aligned with its transmission axis. When the incoming polarization and analyzer are aligned, the transmitted intensity is maximal. Here we normalize that value to 100%. Real optical components introduce losses, so this is a relative ideal prediction rather than a guarantee about every laboratory measurement.','At 0°, cos²(0°) = 1.',{type:'polar',angle:0,caption:'Ideal transmitted intensity: 100% of the chosen reference.'}),
  step('Rotate halfway to a crossed setting','Turn the analyzer by 45° relative to the incoming polarization. Malus’s law gives the classical intensity fraction cos²(45°) = 1/2. For an ideal single-photon transmission test, the same expression gives a probability: each photon is either detected in the transmitted output or it is not. An individual photon is not read as half a click.','50% intensity across many photons is different from half an individual detection.',{type:'polar',angle:45,caption:'At 45°, ideal classical transmitted intensity is 50%.'}),
  step('Cross the two directions','At a relative angle of 90°, the polarizations are orthogonal. The ideal transmission probability is zero, so the transmitted intensity vanishes in the ideal model. Compare this with 45°, where the result is uncertain for a single photon. Orthogonal and nonorthogonal preparations play different roles in quantum measurement.','At 90°, cos²(90°) = 0.',{type:'polar',angle:90,caption:'Crossed ideal analyzer: zero transmission.'}),
  step('Connect direction choices to BB84','BB84 can encode bits using two different polarization bases, such as horizontal/vertical and the two diagonal directions. A matching basis can distinguish its two reference states ideally. An incompatible basis produces uncertain outcomes. Practical QKD receivers can separate two outcomes with dedicated optics and detectors; this single-analyzer intensity picture is only the starting analogy.','A basis is a pair of alternatives, not just one filter angle.',compare('Rectilinear basis',['Horizontal','Vertical'],'Diagonal basis',['+45°','−45°']))
 ]},
 pqc:{title:'Understand post-quantum cryptography',summary:'PQC protects classical systems with mathematical algorithms designed for the quantum threat model.',source:nist,steps:[
  step('Identify what needs protection','Start with a familiar application: two computers need to exchange protected information and verify who they are communicating with. A complete system uses multiple cryptographic functions. Key establishment, encryption and digital signatures have different jobs. Before discussing quantum threats, name the data, identities and keys that the application must protect.','“Security” consists of several distinct tasks.',flow([['Identity','Who is communicating?'],['Shared secret','How are keys established?'],['Protected data','How is the message secured?']],0)),
  step('Understand the quantum threat','Sufficiently capable quantum computers would threaten widely used public-key schemes based on problems such as factoring and discrete logarithms. This does not mean every kind of encryption fails in the same way. It motivates replacing vulnerable components with suitable alternatives and considering how long sensitive information must remain confidential.','The threat depends on the algorithm and on the quantum computer’s capability.',compare('Vulnerable public-key components',['Certain factoring/discrete-log schemes','Need a migration plan'],'Other cryptographic components',['Different quantum effects and parameters','Require their own assessment'])),
  step('See what PQC changes','Post-quantum cryptography uses new mathematical constructions on classical computers and networks. It does not require sending photons or owning a quantum computer. Its algorithms are designed to resist known classical and quantum attacks. Their implementation still needs careful key handling, authentication, correct parameters and ongoing analysis; a label alone is not a security guarantee.','The computers remain classical; the cryptographic algorithms change.',flow([['Classical application','Existing network/service'],['PQC algorithms','Quantum-resistant design'],['Classical messages','Keys, ciphertexts, signatures']],1)),
  step('Separate keys from signatures','A key-establishment mechanism helps parties obtain shared key material. A digital signature lets a verifier check a message’s origin and integrity under its assumptions. They are not interchangeable, and neither alone provides every security property. For example, an application may need a key-establishment component plus authentication and symmetric protection for the actual data.','Choose the primitive for the job, then integrate the whole protocol.',compare('Key establishment',['Purpose: shared key material','Used within a communication protocol'],'Digital signature',['Purpose: origin/integrity verification','Does not itself hide the message'])),
  step('Distinguish PQC from QKD','QKD uses a quantum channel together with authenticated classical communication to establish keys. PQC uses mathematical algorithms on classical equipment. Both need complete security architectures, but their physical requirements and deployment work differ. A website can migrate its cryptographic software without becoming an optical QKD network.','PQC and QKD are different approaches, not two names for the same process.',compare('PQC',['Classical computing/networking','Mathematical cryptographic algorithms'],'QKD',['Quantum signal equipment/channel','Authenticated classical post-processing'])),
  step('Plan and test a migration','First locate where cryptography is used. Then identify compatible implementations and standards, test the whole connection, and deploy in stages with monitoring and recovery plans. Changing an algorithm can affect message sizes, performance and interoperability. A successful classroom example is a migration plan with observable checks, rather than a claim that every system is now secure.','Inventory → test → deploy carefully → monitor.',flow([['Inventory','Find dependencies'],['Validate','Test full connections'],['Roll out','Stage changes'],['Monitor','Verify and maintain']],1))
 ]},
 qiskit:{title:'Turn a circuit idea into a program',summary:'Read the small program as a recipe and distinguish drawing, simulation and hardware execution.',source:ref('IBM · Construct circuits','https://quantum.cloud.ibm.com/docs/en/guides/construct-circuits'),steps:[
  step('Create places for quantum and classical information','A small Qiskit circuit can have one qubit and one classical bit. The qubit carries the state while the circuit operates. The classical bit stores a measurement result. In QuantumCircuit(1, 1), the two counts describe these different resources. Creating the circuit object does not send a job to a quantum processor.','One quantum wire and one classical storage location have different roles.',compare('Qubit q[0]',['Carries the quantum state','Receives quantum operations'],'Classical bit c[0]',['Stores 0 or 1','Receives a measurement result'])),
  step('Add the gate in the intended order','The instruction qc.h(0) appends H on qubit zero. Starting with the usual |0⟩ preparation, the ideal state becomes |+⟩. A circuit is an ordered list of instructions, so later calls append later operations. Predict the state after each instruction before asking a simulator or a physical processor to run it.','qc.h(0) specifies the gate and its target qubit.',circuit(['H'],'Program instruction qc.h(0) prepares equal Z probabilities from |0⟩.')),
  step('Add a measurement destination','The instruction qc.measure(0, 0) measures qubit zero in the computational Z basis and stores the result in classical bit zero. A single shot records one outcome. To estimate a distribution, request repeated executions that begin with fresh preparations. A sequence of many measurements on one already collapsed state is a different experiment.','Measurement maps the quantum prediction to a recorded classical value.',flow([['q[0]','Prepared |+⟩'],['Z measurement','0 or 1'],['c[0]','One recorded bit']],1)),
  step('Inspect the drawing before execution','Calling qc.draw() produces a representation of the instructions. It does not itself collect measurement samples or run the circuit on hardware. The drawing is still useful: check the wire count, gate order and measurement destinations. Then choose an appropriate execution method, either an ideal/noisy simulator or an authorized hardware service.','A circuit picture is a plan, not an experimental result.',compare('Draw',['Inspect instructions','No measurement counts produced'],'Execute',['Choose simulator or hardware','Collect shot outcomes'])),
  step('Interpret the returned counts','Suppose a run returns 96 zeros and 104 ones from 200 independent shots. Convert counts to frequencies: 96/200 = 48% and 104/200 = 52%. Compare with the ideal 50/50 prediction. Small differences can come from finite sampling; hardware may add noise. Record the method and settings so another learner can interpret the result.','Counts are classical data about repeated circuit executions.',bars(['0','1'],[.48,.52],'Illustrative 200-shot result: 96 zeros, 104 ones.'))
 ]},
 python:{title:'Use Python to connect predictions and counts',summary:'Calculate a probability, organize observations and explain what the numbers mean.',source:ref('Python · Numbers and lists','https://docs.python.org/3/tutorial/introduction.html'),steps:[
  step('Give each quantity a clear meaning','A Python variable stores a value used by the program. Before calculating, label each value: an angle, an amplitude, a probability or a count. They are related but not interchangeable. For example, alpha = 0.6 represents an amplitude in this example; the corresponding probability is 0.36, not 0.6.','Write units and meanings alongside the numbers.',compare('Amplitude',['alpha = 0.6','May have sign/complex phase'],'Probability',['abs(alpha) ** 2 = 0.36','Between 0 and 1'])),
  step('Check a complete probability model','Choose real amplitudes alpha = 0.6 and beta = 0.8. Their squared magnitudes are 0.36 and 0.64, which add to one. This is a valid normalized one-qubit state in the chosen basis. For complex amplitudes, use abs(value) ** 2 to include both real and imaginary parts correctly.','A valid probability distribution must sum to 1.',bars(['0','1'],[.36,.64],'|0.6|² = 0.36 and |0.8|² = 0.64.')),
  step('Convert angles consistently','Python’s trigonometric functions use radians. If the Bloch-sphere control reports theta = 60 degrees, first convert it with radians(theta). Then the qubit formula uses cos(theta_radians / 2) ** 2. Its result is 0.75. Forgetting either the degree conversion or the half-angle changes the prediction.','Degrees → radians → half-angle → square.',flow([['60°','Slider value'],['π/3 radians','Convert units'],['cos²(π/6)','Use half-angle'],['0.75','Probability of 0']],2)),
  step('Summarize a list of outcomes','Consider the illustrative sample [0, 1, 0, 0, 1]. It contains five classical measurement records: three zeros and two ones. Count each value, then divide by the total. The observed frequencies are 60% and 40%. They describe this sample and do not reveal five simultaneous quantum states stored inside a Python list.','Three zeros divided by five trials gives 0.6.',bits([['Trial',['1','2','3','4','5']],['Outcome',['0','1','0','0','1']]],'Illustrative data: zeros = 3, ones = 2, total = 5.')),
  step('Separate prediction from observation','Compare the calculated probability with a measured or simulated frequency. A small sample can fluctuate substantially, so report its size. A classical program that samples a probability model is a simulation, not a physical quantum experiment. Label the data source and retain the inputs so the calculation can be reproduced and checked.','State both the theoretical probability and the number of observed trials.',compare('Prediction',['From amplitudes and circuit','Does not fluctuate between identical calculations'],'Observed frequency',['From a finite sample','Can differ across runs']))
 ]},
 network:{title:'Separate the message, the key and identity',summary:'Follow a communication task before introducing quantum key distribution.',source:nist,steps:[
  step('Name the communication task','Alice wants Bob to receive a message across a network. The channel is the route the information takes, such as a wired or wireless connection. Someone else might be able to observe or alter traffic. First distinguish what Alice wants to send from the protections used while sending it.','Sender, channel and receiver are separate parts of the story.',flow([['Alice','Creates the message'],['Channel','Carries information'],['Bob','Receives the message']],0)),
  step('Distinguish plaintext and ciphertext','Plaintext is the readable message before encryption. Ciphertext is the transformed data sent through the channel. An encryption method uses a key to control this transformation. Bob needs the appropriate key and method to recover the plaintext. Seeing ciphertext should not, under the intended assumptions, reveal the protected message.','The transmitted data and the secret key serve different roles.',flow([['Plaintext','Readable message'],['Encrypt with key','Transform the data'],['Ciphertext','Send across channel'],['Decrypt','Recover the message']],1)),
  step('Ask how the key is established','If Alice and Bob use a shared-secret scheme, they need suitable matching key material. That key must be established or delivered somehow. QKD is one approach to this key-establishment task. It does not mean sending the readable message itself as the sequence of BB84 photons, nor does it replace the entire application protocol.','Establishing a key and encrypting a message are different stages.',compare('Key establishment',['Obtain matching key material','QKD is one possible approach'],'Message protection',['Use an appropriate cryptographic scheme','Secure the application’s actual data'])),
  step('Verify who is on the other end','Encryption alone does not establish a peer’s identity. Authentication lets the participants check who produced a communication and whether it was modified, according to the method used. QKD also needs authenticated classical exchanges. Otherwise an attacker could impersonate each participant while conducting separate exchanges with the other.','A private-looking exchange still needs an identity check.',flow([['Claimed identity','“I am Bob”'],['Authentication','Verify the claim/exchange'],['Accepted peer','Continue the intended protocol']],1)),
  step('Combine the protections','A complete communication design addresses confidentiality, integrity and authentication as needed. It also manages keys and handles errors. In the workshop, trace where each function occurs instead of treating the word quantum as a complete solution. Then follow the QKD walkthrough to see how quantum signals contribute specifically to establishing key material.','Name the security job performed at each stage.',compare('Questions to ask',['Can outsiders read it?','Can changes be detected?'],'Also ask',['Who sent it?','How are keys handled?']))
 ]},
 waves:{title:'Read a wave before comparing phases',summary:'Use amplitude, period, frequency and phase to predict what an oscilloscope should show.',source:ref('Workshop · Applied energy waves circuit','/src/applied-waves-circuit.svg'),steps:[
  step('Measure voltage relative to a reference','An oscilloscope plots voltage against time. Voltage is a difference between two points, so the reference connection matters. In the supervised circuit, use the approved common ground and low-voltage sources. The plotted curve represents an electrical signal, not the path of an electron or a direct image of a quantum state.','Horizontal axis: time. Vertical axis: voltage.',flow([['Source','Creates a voltage wave'],['Approved connections','Define the reference'],['Oscilloscope','Plots voltage vs time']],2)),
  step('Distinguish peak from peak-to-peak','For a zero-offset sine wave that ranges from −1 V to +1 V, the peak amplitude is 1 V and the peak-to-peak value is 2 Vpp. These are two descriptions of the same wave height. Record which one the instrument setting uses; otherwise a predicted result can seem wrong by a factor of two.','Vpp measures the full distance from minimum to maximum.',compare('Peak amplitude',['Center to maximum','Example: 1 V'],'Peak-to-peak',['Minimum to maximum','Example: 2 Vpp'])),
  step('Connect period and frequency','The period T is the time for one complete cycle. Frequency f counts cycles per second and is measured in hertz. They are related by T = 1/f. For a 1 kHz signal, T = 1/1000 second = 1 millisecond. Check the oscilloscope timebase against this predicted spacing between peaks.','1 kHz means one cycle every 1 ms.',flow([['Frequency','1000 cycles/second'],['T = 1/f','1/1000 second'],['Period','1 millisecond']],1)),
  step('Compare two signals using relative phase','For two waves with the same frequency, relative phase describes how their cycles line up. Zero degrees means matching peaks; 180° means a peak meets a trough. A 90° offset is one quarter of a cycle. Keep frequency and amplitude fixed when testing phase so the effect of one changing parameter is clear.','At 1 kHz, a quarter-period delay is 0.25 ms.',bits([['Phase',['0°','90°','180°']],['Cycle offset',['0','1/4','1/2']],['Time at 1 kHz',['0 ms','0.25 ms','0.5 ms']]],'These offsets describe two signals of the same frequency.')),
  step('Predict the equal-resistor output','With synchronized equal 2 Vpp inputs and an ideal equal-resistor combiner measured by a high-impedance scope, the output is their average. Its predicted height is 2 Vpp at 0°, about 1.414 Vpp at 90°, and zero at 180°. Real tolerances and source settings can cause deviations. Keep the resistors in place; do not directly join active outputs.','The passive combiner averages the signals; it does not double the aligned voltage.',bits([['Relative phase',['0°','90°','180°']],['Ideal Vout',['2.000 Vpp','1.414 Vpp','0 Vpp']]],'Classical voltage prediction; it is not a measurement of quantum amplitudes.'))
 ]},
 process:{title:'Turn a concept into evidence',summary:'Use a repeatable learning cycle: explain, predict, test and interpret.',source:ref('IBM · Quantum learning resources','https://quantum.cloud.ibm.com/learning'),steps:[
  step('Ask one clear question','Begin with a question small enough to test. For example: how does changing relative phase affect the final probability of zero in an H–phase–H circuit? Identify the quantity you will change and the quantity you will observe. This gives the demonstration a purpose before you touch a control or collect a measurement.','One changing parameter makes the explanation easier to follow.',flow([['Question','What changes?'],['Input','One chosen parameter'],['Observation','One measured/calculated quantity']],0)),
  step('Build a prediction before the trial','Explain the model in words, then calculate or sketch its prediction. For the phase example, try 0°, 90° and 180° before running the demonstration. A prediction gives you something specific to compare with the result. Writing it first avoids turning any observation afterward into an apparently successful outcome.','Predict first, then operate the model or instrument.',bits([['Phase',['0°','90°','180°']],['Predicted P(0)',['1','0.5','0']]],'Example prediction for the complete H → P(φ) → H circuit.')),
  step('Choose and label the method','A browser model calculates ideal predictions. A classical simulator samples an assumed quantum model. A physical experiment measures a device and includes its limitations. These are valuable but different sources of evidence. Label which method you used and record the setup; do not present a software animation as a measurement from quantum hardware.','Every result needs a clear description of where it came from.',compare('Software model',['Chosen assumptions','Calculated/simulated results'],'Physical experiment',['Equipment and settings','Measured data with uncertainty'])),
  step('Record enough for someone to repeat it','Save the preparation, operations, measurement basis, number of trials and observed counts for a circuit experiment. For the wave lab, record frequency, amplitudes, phase, connections and scope settings. A useful technician record also notes unexpected behavior. Repeatable evidence is more informative than a screenshot with no explanation of its settings.','A result without settings is difficult to interpret or reproduce.',flow([['Setup','Record settings'],['Trial','Change one variable'],['Results','Keep units/counts'],['Repeat','Check consistency']],2)),
  step('Explain both the result and its limits','Compare observation with prediction and give a reason for agreement or difference. Distinguish finite-sample variation, model assumptions and possible equipment errors. End with a supported claim and one next question. For example, classical wave cancellation illustrates phase, but it does not demonstrate entanglement. A good explanation identifies what the evidence actually establishes.','A clear limit makes the conclusion more accurate.',compare('Supported conclusion',['What the data show','Which assumptions were used'],'Next investigation',['What remains untested','One useful follow-up question']))
 ]}
};

